 public function testManagedConsumerDeniesOldTransactionAcrossActualCommittedSamePixelRevision():void {
  $f=$this->photo();$photo=new CustomerPhotoSelection();global $wpdb;$primary=$wpdb;$other=new wpdb(DB_USER,DB_PASSWORD,DB_NAME,DB_HOST);$other->set_prefix($primary->prefix);$other->query('SET SESSION innodb_lock_wait_timeout=2');$modes=['READ-COMMITTED'=>'READ COMMITTED','REPEATABLE-READ'=>'REPEATABLE READ','READ-UNCOMMITTED'=>'READ UNCOMMITTED','SERIALIZABLE'=>'SERIALIZABLE'];$prior=strtoupper((string)$primary->get_var('SELECT @@session.tx_isolation'));self::assertArrayHasKey($prior,$modes);$next=null;
  try {self::assertNotFalse($primary->query('COMMIT'));self::assertNotFalse($primary->query('SET autocommit=1'));self::assertNotFalse($primary->query('SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ'));self::assertSame($f['selection']['sha256'],PrintifyApiApprovalFixture::checked($photo->forOrder('personalized_pod',$f['order'],$f['line']))['sha256']);self::assertNotFalse($primary->query('START TRANSACTION WITH CONSISTENT SNAPSHOT'));$first=$photo->forOrder('personalized_pod',$f['order'],$f['line']);self::assertWPError($first);self::assertSame('photo_current_read_caller_transaction',$first->get_error_code());self::assertSame('1',(string)$primary->get_var('SELECT @@session.in_transaction'));
   $wpdb=$other;self::assertNotFalse($other->query('SET SESSION innodb_lock_wait_timeout=2'));wp_set_current_user($f['customer']);$request=$f['request'];$request['request_key']='two-connection-same-photo';$request['expected_head']=$f['version']['sha256'];$version=PrintifyApiApprovalFixture::checked((new CustomerEditorRepository())->upload($f['session'],$request));$next=PrintifyApiApprovalFixture::checked($photo->submit($f['session'],$version['sha256'],1));$this->fixture->owner();PrintifyApiApprovalFixture::checked($photo->review($f['session'],$next['sha256'],2,'APPROVED','Synthetic independently committed second selection'));self::assertSame('0',(string)$other->get_var('SELECT @@session.in_transaction'));$fresh=PrintifyApiApprovalFixture::checked($photo->forOrder('personalized_pod',$f['order'],$f['line']));self::assertSame($next['sha256'],$fresh['sha256']);self::assertSame($f['selection']['submission_id'],$next['submission_id']);self::assertNotSame($f['selection']['sha256'],$next['sha256']);
   $wpdb=$primary;$stale=(new PersonalizationCurrentness())->forOrder($f['order']);self::assertWPError($stale,'The B consumer must deny unproven current reads inside a managed caller transaction.');self::assertSame('photo_current_read_caller_transaction',$stale->get_error_code());self::assertSame('1',(string)$primary->get_var('SELECT @@session.in_transaction'));
  }finally{$wpdb=$primary;$primary->query('ROLLBACK');$primary->query('SET autocommit=1');$primary->query('SET SESSION TRANSACTION ISOLATION LEVEL '.$modes[$prior]);$other->query('ROLLBACK');$other->close();$this->fixture->owner();}
 }
