 public function testHeldLastCanonicalProjectionReadCannotReleaseAfterActorLoss():void {
  foreach(['logout','capability']as $mode){$this->fixture->owner();[$order,$intent]=$this->textHeld();$actor=wp_get_current_user();$sourceReads=0;$canonicalReads=0;$changed=false;$hook=static function(string $sql)use($mode,$actor,&$sourceReads,&$canonicalReads,&$changed):string{if(str_starts_with($sql,'SELECT o.id,o.channel'))++$sourceReads;if($sourceReads>=2&&str_starts_with($sql,'SELECT ps.id,ps.personalization_schema_id')&&++$canonicalReads===2){$changed=true;if($mode==='logout')wp_set_current_user(0);else $actor->add_cap('manage_digiforge_pod',false);}return $sql;};add_filter('query',$hook);try{self::assertWPError((new HeldFulfillmentPreparation())->prepare('personalized_pod',$order,$intent),'The final canonical projection read cannot release held metadata after logout or POD capability loss.');}finally{remove_filter('query',$hook);$actor->add_cap('manage_digiforge_pod');$this->fixture->owner();}self::assertTrue($changed);}
 }
