  self::assertTrue(class_exists(\DigiForge\Orders\PersonalizationReadContext::class));$f=$this->photo(false);$context=\DigiForge\Orders\PersonalizationReadContext::capture('personalized_pod',$f['order']);self::assertNotWPError($context);global $wpdb;$primary=$wpdb;$other=new wpdb(DB_USER,DB_PASSWORD,DB_NAME,DB_HOST);$other->set_prefix($primary->prefix);$other->query('SET SESSION innodb_lock_wait_timeout=2');$line=$primary->get_row($primary->prepare('SELECT * FROM '.Tables::order_line_items().' WHERE id=%d',$f['line']),ARRAY_A);$mapping=$primary->get_row($primary->prepare('SELECT * FROM '.Tables::pod_mappings().' WHERE id=%d',$line['provider_mapping_id']),ARRAY_A);$table=Tables::pod_mappings();$field='mapping_version';$value='independently committed changed mapping';if($mode==='ownership'){$table=Tables::pod_business_mappings();$mapping=$primary->get_row($primary->prepare('SELECT * FROM '.$table.' WHERE provider_mapping_id=%d',$line['provider_mapping_id']),ARRAY_A);$field='state';$value='REVIEW_REQUIRED';}elseif($mode==='version'){$table=Tables::product_versions();$mapping=$primary->get_row($primary->prepare('SELECT * FROM '.$table.' WHERE id=%d',$line['product_version_id']),ARRAY_A);$field='notes';$value='independently committed changed version';}
  try{self::assertNotFalse($primary->query('START TRANSACTION WITH CONSISTENT SNAPSHOT'));self::assertSame($mapping,$primary->get_row($primary->prepare('SELECT * FROM '.$table.' WHERE id=%d',$mapping['id']),ARRAY_A));self::assertSame(1,$other->update($table,[$field=>$value],['id'=>$mapping['id']]));self::assertSame('0',(string)$other->get_var('SELECT @@session.in_transaction'));self::assertSame($mapping,$primary->get_row($primary->prepare('SELECT * FROM '.$table.' WHERE id=%d',$mapping['id']),ARRAY_A));$controls=[];$record=static function(string $sql)use(&$controls):string{if(preg_match('/^(?:COMMIT|ROLLBACK|START TRANSACTION|SET .*TRANSACTION)/i',$sql))$controls[]=$sql;return $sql;};$quiet=$primary->suppress_errors(true);add_filter('query',$record);try{$changed=$context->forOrder($f['order'],true);$lockingError=$primary->last_error;}finally{remove_filter('query',$record);$primary->suppress_errors($quiet);}self::assertWPError($changed,'Current FOR UPDATE evidence must deny the independently committed row, including a failstop SQL conflict, unlike the old ordinary snapshot.');self::assertContains($changed->get_error_code(),['order_photo_context_changed','order_photo_context_unavailable']);self::assertSame([],$controls,'The context must not commit, rollback or reset the caller frame; MariaDB may abort a conflicting locking read.');if($changed->get_error_code()==='order_photo_context_unavailable')self::assertNotSame('',$lockingError);self::assertWPError($context->validate(),'A failed current read permanently invalidates this decision.');}finally{$primary->query('ROLLBACK');$other->update($table,$mapping,['id'=>$mapping['id']],array_fill(0,count($mapping),'%s'));$other->close();self::assertNotWPError($context->release());}
 }
